import json
T=[]
def q(ref,cat,text,opts,exp,case=None):
    T.append(dict(ref=ref,cat=cat,q=text,opts=opts,exp=exp,**({'case':case} if case else {})))
# ---------- Chapter 5: merchandising (perpetual unless stated) ----------
q('QS-5-1','c5',"Kerr Co. buys $5,000 of merchandise on account, terms 2/10, n/30, returns $400 of it, and pays the balance within the discount period. How much cash is paid?",["$4,508","$4,600","$4,900","$4,410"],"(5,000 − 400) × 98% = 4,508. The discount applies only to the amount still owed.")
q('QS-5-2','c5',"Credit terms of 2/10, n/60 mean:",["A 2% discount if paid within 10 days; otherwise the full amount is due within 60 days","A 10% discount if paid within 2 days","2% interest is charged after 10 days","The full amount is due in 10 days and 2% is refunded after 60 days"],"The discount rate comes first, then the discount period, then the credit period.")
q('QS-5-4','c5',"Which cost is NOT included in the cost of merchandise inventory?",["Sales commissions paid to salespeople","Freight-in paid by the buyer","The purchase price less discounts","Insurance while the goods are in transit to the buyer"],"Inventory includes all costs to bring goods to a saleable condition and location. Selling costs are expenses.")
q('QS-5-5','c5',"Net sales are $120,000, cost of sales is $72,000 and operating expenses are $30,000. What is gross profit?",["$48,000","$18,000","$90,000","$42,000"],"Gross profit = net sales − cost of sales = 120,000 − 72,000. Net income would be 18,000.")
q('QS-5-6','c5',"An invoice for $3,000 has terms 3/15, n/45. What is the net amount if it is paid within 15 days?",["$2,910","$2,940","$3,000","$2,970"],"3,000 × 97% = 2,910.")
q('QS-5-7','c5',"A $3,000 purchase on terms 2/10, n/30 is paid within the discount period (perpetual system). Payment entry?",["Dr Accounts Payable 3,000; Cr Merchandise Inventory 60; Cr Cash 2,940","Dr Accounts Payable 3,000; Cr Purchases Discounts 60; Cr Cash 2,940","Dr Accounts Payable 2,940; Cr Cash 2,940","Dr Merchandise Inventory 60; Dr Accounts Payable 2,940; Cr Cash 3,000"],"Under a perpetual system the discount reduces the cost of inventory directly.")
q('QS-5-8','c5',"The same $3,000 purchase (2/10, n/30) is paid after the discount period. Payment entry?",["Dr Accounts Payable 3,000; Cr Cash 3,000","Dr Accounts Payable 3,000; Cr Merchandise Inventory 60; Cr Cash 2,940","Dr Accounts Payable 2,940; Dr Discounts Lost 60; Cr Cash 3,000","Dr Merchandise Inventory 3,000; Cr Cash 3,000"],"The discount was missed, so the full invoice is paid (gross method).")
q('QS-5-9','c5',"Goods are sold for $2,000 on account (cost $1,200), terms 2/10, n/30. The customer pays within 10 days. Collection entry?",["Dr Cash 1,960; Dr Sales Discounts 40; Cr Accounts Receivable 2,000","Dr Cash 2,000; Cr Accounts Receivable 2,000","Dr Cash 1,960; Cr Accounts Receivable 1,960","Dr Cash 1,960; Dr Cost of Sales 40; Cr Accounts Receivable 2,000"],"Sales Discounts is a contra-revenue account.")
q('QS-5-9','c5',"A customer returns $300 of goods (cost $180) that can be resold. Besides Dr Sales Returns and Allowances 300, Cr Accounts Receivable 300, the seller records:",["Dr Merchandise Inventory 180; Cr Cost of Sales 180","Dr Cost of Sales 180; Cr Merchandise Inventory 180","Dr Merchandise Inventory 300; Cr Sales 300","No second entry"],"Under a perpetual system the goods go back into inventory and cost of sales is reduced.")
q('QS-5-21','c5',"Net sales are $250,000 and cost of sales is $160,000. What is the gross margin ratio?",["36%","64%","56%","1.56"],"(250,000 − 160,000) ÷ 250,000 = 36%.")
q('QS-5-22','c5',"In a multiple-step income statement, interest expense is reported under:",["Other revenues and expenses (non-operating)","Selling expenses","General and administrative expenses","Cost of sales"],"Operating income is computed before non-operating items such as interest.")
q('QS-5-23','c5',"In closing entries for a merchandiser, Sales Discounts and Sales Returns and Allowances are:",["Credited, with Income Summary debited","Debited, with Income Summary credited","Not closed — they are permanent accounts","Closed to Merchandise Inventory"],"They have debit balances, so they are closed with credits, together with cost of sales and expenses.")
q('QS-5-26','c5',"Cash $8,000; short-term investments $2,000; accounts receivable $10,000; inventory $15,000; prepaid expenses $1,000; current liabilities $16,000. Acid-test ratio?",["1.25","2.25","0.63","1.19"],"Quick assets = 8,000 + 2,000 + 10,000 = 20,000; 20,000 ÷ 16,000 = 1.25. Inventory and prepaids are excluded.")
q('E-5-26','c5',"Using the same data (current assets $36,000, current liabilities $16,000), what is the current ratio?",["2.25","1.25","2.00","0.44"],"36,000 ÷ 16,000 = 2.25.")
q('QS-5-27A','c5',"Under a periodic inventory system, a purchase of merchandise on account is debited to:",["Purchases","Merchandise Inventory","Cost of Sales","Accounts Payable"],"A periodic system uses temporary accounts (Purchases, Purchases Returns, Purchases Discounts, Freight-In).")
q('QS-5-28A','c5',"Periodic system: a $3,000 invoice (2/10, n/30) is paid within the discount period. Entry?",["Dr Accounts Payable 3,000; Cr Purchases Discounts 60; Cr Cash 2,940","Dr Accounts Payable 3,000; Cr Merchandise Inventory 60; Cr Cash 2,940","Dr Purchases 2,940; Cr Cash 2,940","Dr Accounts Payable 3,000; Cr Cash 3,000"],"The discount goes to the contra account Purchases Discounts.")
q('E-5-4','c5',"Which sequence describes a merchandiser's operating cycle?",["Purchase inventory → sell on credit → collect cash","Sell → purchase inventory → collect cash","Collect cash → sell → purchase inventory","Purchase inventory → collect cash → sell"],"Cash goes into inventory, inventory becomes receivables, receivables become cash.")
q('E-5-8','c5',"A buyer pays $150 freight on goods bought FOB shipping point (perpetual). Entry?",["Dr Merchandise Inventory 150; Cr Cash 150","Dr Delivery Expense 150; Cr Cash 150","Dr Freight-In 150; Cr Accounts Payable 150","No entry — the seller pays"],"FOB shipping point: the buyer owns the goods in transit, and freight-in is part of inventory cost.")
q('E-5-8','c5',"A seller pays $150 to ship goods to a customer under FOB destination. Entry?",["Dr Delivery Expense 150; Cr Cash 150","Dr Merchandise Inventory 150; Cr Cash 150","Dr Accounts Receivable 150; Cr Cash 150","Dr Cost of Sales 150; Cr Cash 150"],"Freight-out is a selling expense for the seller.")
q('E-5-9','c5',"Periodic data: beginning inventory $10,000; purchases $50,000; purchases discounts $1,000; purchases returns $2,000; freight-in $1,500; ending inventory $12,000. Cost of sales?",["$46,500","$49,500","$58,500","$43,500"],"Net purchases 50,000 − 1,000 − 2,000 + 1,500 = 48,500; 10,000 + 48,500 − 12,000 = 46,500.")
q('E-5-22','c5',"Sales $80,000; sales returns and allowances $3,000; sales discounts $1,200. Net sales?",["$75,800","$77,000","$78,800","$84,200"],"80,000 − 3,000 − 1,200 = 75,800.")
q('E-5-23','c5',"The Merchandise Inventory account shows $22,500, but a physical count finds $21,900. Adjusting entry for shrinkage?",["Dr Cost of Sales 600; Cr Merchandise Inventory 600","Dr Merchandise Inventory 600; Cr Cost of Sales 600","Dr Loss on Sales 600; Cr Sales 600","No entry until next year"],"Shrinkage is usually charged to cost of sales.")
q('QS-5-43B','c5',"At year-end a company expects $1,500 of this year's sales (cost $900) to be returned next year. Which liability is credited?",["Sales Refund Payable","Accounts Receivable","Unearned Revenue","Allowance for Doubtful Accounts"],"Entries: Dr Sales Returns and Allowances 1,500, Cr Sales Refund Payable 1,500; Dr Inventory Returns Estimated 900, Cr Cost of Sales 900.")
q('QS-5-42C','c5',"Net method: a $4,000 purchase on terms 2/10, n/30 is recorded in Merchandise Inventory at:",["$3,920","$4,000","$4,080","$3,600"],"The net method records the purchase net of the discount: 4,000 × 98%. A missed discount is later debited to Discounts Lost.")
q('P-5-2A','c5',"Perpetual: bought $6,000 of goods on terms 2/10, n/30; returned $500; paid the rest within 10 days. Net cost added to Merchandise Inventory?",["$5,390","$5,500","$5,880","$6,000"],"6,000 − 500 − (5,500 × 2% = 110) = 5,390.")
# ---------- Chapter 6: inventories ----------
CS="Beginning inventory 100 units @ $10; March purchase 150 units @ $12; August purchase 200 units @ $13. 300 units were sold during the year (periodic system)."
q('QS-6-1','c6',"Goods shipped FOB destination are in transit at the seller's year-end. Whose inventory are they?",["The seller's","The buyer's","The carrier's","Split between buyer and seller"],"Under FOB destination, ownership passes when the goods arrive.")
q('E-6-1','c6',"Goods held by a company on consignment for another firm belong to:",["The consignor","The consignee","The final customer","Whoever paid the freight"],"The consignee only sells the goods for the consignor; it never owns them.")
q('QS-6-2','c6',"Purchase price $12,000; freight-in $600; import duties $900; insurance in transit $200; advertising for the goods $500. Cost of inventory?",["$13,700","$14,200","$12,000","$13,500"],"12,000 + 600 + 900 + 200 = 13,700. Advertising is a selling expense.")
q('QS-6-29','c6',"Under IAS 2, which cost is expensed rather than included in inventory?",["Abnormal amounts of wasted materials","Import duties","Freight to bring goods to the store","The purchase price"],"Abnormal waste, later storage and selling costs are expenses.")
q('QS-6-9','c6',"What is the cost of goods available for sale?",["$5,400","$3,800","$4,500","$1,950"],"1,000 + 1,800 + 2,600 = 5,400 for 450 units.",CS)
q('QS-6-5A','c6',"FIFO (periodic): ending inventory?",["$1,950","$1,600","$1,800","$3,450"],"150 units, all from the latest purchase: 150 × 13 = 1,950. Cost of sales = 5,400 − 1,950 = 3,450.",CS)
q('QS-6-6A','c6',"LIFO (periodic): cost of sales?",["$3,800","$3,450","$3,600","$1,600"],"Ending inventory is the oldest 150 units: 100 × 10 + 50 × 12 = 1,600; cost of sales = 5,400 − 1,600 = 3,800.",CS)
q('QS-6-7A','c6',"Weighted average (periodic): ending inventory?",["$1,800","$1,950","$1,600","$3,600"],"Average cost 5,400 ÷ 450 = $12.00; 150 × 12 = 1,800.",CS)
q('QS-6-15A','c6',"Specific identification: the 300 units sold were 80 from beginning inventory, 120 from March and 100 from August. Cost of sales?",["$3,540","$3,600","$3,450","$3,800"],"80 × 10 + 120 × 12 + 100 × 13 = 800 + 1,440 + 1,300 = 3,540.",CS)
CP="Perpetual system. Jan 1 beginning 50 units @ $20; Jan 5 purchase 100 @ $22; Jan 10 sale 80 units; Jan 20 purchase 60 @ $25; Jan 25 sale 70 units."
q('QS-6-18','c6',"FIFO (perpetual): cost of sales for January?",["$3,200","$3,480","$3,318","$1,500"],"Jan 10: 50 × 20 + 30 × 22 = 1,660. Jan 25: 70 × 22 = 1,540. Total 3,200; ending 60 × 25 = 1,500.",CP)
q('QS-6-4','c6',"LIFO (perpetual): ending inventory on January 31?",["$1,220","$1,500","$1,382","$1,000"],"Jan 10: 80 × 22. Jan 25: 60 × 25 + 10 × 22. Left: 10 × 22 + 50 × 20 = 1,220.",CP)
q('QS-6-3','c6',"Weighted average (perpetual / moving average): cost of sales for January, to the nearest dollar?",["$3,318","$3,200","$3,480","$3,290"],"After Jan 5: 3,200 ÷ 150 = 21.33; Jan 10 COGS 1,706.67. After Jan 20: 2,993.33 ÷ 130 = 23.03; Jan 25 COGS 1,611.79. Total ≈ 3,318.",CP)
q('QS-6-16','c6',"When purchase prices are rising, which method gives the highest gross profit?",["FIFO","LIFO","Weighted average","All give the same gross profit"],"FIFO charges the older, cheaper costs to cost of sales.")
q('QS-6-11','c6',"Which cost flow method is NOT permitted under IFRS (IAS 2)?",["LIFO","FIFO","Weighted average","Specific identification"],"IFRS prohibits LIFO; US GAAP allows it.")
q('E-6-11','c6',"A company's FIFO cost of sales is lower than its LIFO cost of sales. This suggests that purchase prices were:",["Rising","Falling","Constant","Impossible to tell"],"With rising prices, LIFO charges the newer, higher costs to cost of sales.")
q('QS-6-17','c6',"Item A: cost $5,000, NRV $4,600. Item B: cost $3,000, NRV $3,400. Item C: cost $2,000, NRV $1,800. Inventory at the lower of cost and NRV, item by item?",["$9,400","$10,000","$9,800","$9,000"],"4,600 + 3,000 + 1,800 = 9,400.")
q('E-6-18','c6',"Continuing: total cost is $10,000 and the item-by-item amount is $9,400. Write-down entry?",["Dr Cost of Sales 600; Cr Merchandise Inventory 600","Dr Merchandise Inventory 600; Cr Cost of Sales 600","Dr Loss 400; Cr Merchandise Inventory 400","No entry — inventory stays at cost"],"Inventory is reduced to the lower of cost and net realizable value.")
q('QS-6-21','c6',"Cost of sales $90,000; beginning inventory $14,000; ending inventory $16,000. Inventory turnover?",["6.0 times","5.6 times","6.4 times","3.0 times"],"Average inventory (14,000 + 16,000) ÷ 2 = 15,000; 90,000 ÷ 15,000 = 6.0.")
q('E-6-19','c6',"Using the same data, days' sales in inventory (based on ending inventory, 365 days)?",["About 65 days","About 61 days","About 57 days","About 6 days"],"16,000 ÷ 90,000 × 365 = 64.9 days.")
q('QS-6-22B','c6',"Beginning inventory $20,000; purchases $80,000; net sales $120,000; normal gross profit ratio 30%. Estimated ending inventory (gross profit method)?",["$16,000","$64,000","$36,000","$4,000"],"Estimated cost of sales = 120,000 × 70% = 84,000; 100,000 − 84,000 = 16,000.")
q('E-6-13B','c6',"Goods available: $60,000 at cost, $100,000 at retail. Net sales at retail $70,000. Estimated ending inventory at cost (retail method)?",["$18,000","$30,000","$42,000","$12,000"],"Ending at retail 30,000 × cost ratio 60% = 18,000.")
# ---------- Chapter 7: accounting information systems ----------
q('QS-7-1','c7',"Which is NOT one of the five basic components of an accounting information system?",["Internal auditors","Source documents","Information processors","Output devices"],"The components are source documents, input devices, information processors, information storage and output devices.")
q('QS-7-2','c7',"\"The system should adapt to changes in the company, its operations and needs.\" This describes the principle of:",["Flexibility","Control","Compatibility","Cost-benefit"],"Compatibility means fitting the company's activities; flexibility means adapting to change.")
q('QS-7-3','c7',"Accounts Receivable in the general ledger, supported by a ledger of individual customer accounts, is called a:",["Controlling account","Subsidiary account","Special journal","Contra account"],"Its balance equals the total of the subsidiary ledger.")
q('QS-7-4','c7',"Customer balances in the AR subsidiary ledger: Adams $1,200, Burke $3,450, Chen $800. What should the Accounts Receivable controlling account show?",["$5,450","$4,650","$3,450","$5,850"],"1,200 + 3,450 + 800 = 5,450.")
q('QS-7-5','c7',"In which journal is a sale of merchandise on credit recorded?",["Sales journal","Cash receipts journal","Purchases journal","General journal"],"The sales journal records credit sales only.")
q('QS-7-9','c7',"In which journal is a purchase of merchandise on credit recorded?",["Purchases journal","Cash disbursements journal","Sales journal","General journal"],"The purchases journal records purchases on credit.")
q('E-7-2','c7',"In which journal is a payment of cash to a creditor recorded?",["Cash payments (disbursements) journal","Purchases journal","Cash receipts journal","General journal"],"All cash payments go to the cash disbursements journal.")
q('E-7-4','c7',"In which journal is a sales return on account recorded (special journals: sales, purchases, cash receipts, cash payments)?",["General journal","Sales journal","Cash receipts journal","Cash disbursements journal"],"Returns and other non-routine entries go to the general journal.")
q('E-7-8','c7',"In which journal is a collection from a customer on account recorded?",["Cash receipts journal","Sales journal","General journal","Cash disbursements journal"],"All cash received goes to the cash receipts journal.")
q('QS-7-6','c7',"At month-end, the sales journal total (perpetual system) is posted as:",["Dr Accounts Receivable, Cr Sales; and Dr Cost of Sales, Cr Merchandise Inventory","Dr Sales, Cr Accounts Receivable","Dr Cash, Cr Sales","Dr Accounts Receivable, Cr Cash"],"The column totals go to the general ledger accounts.")
q('E-7-1','c7',"Individual amounts in the sales journal are posted daily to:",["Customer accounts in the accounts receivable subsidiary ledger","The Sales account in the general ledger","The cash receipts journal","Creditor accounts in the accounts payable ledger"],"This keeps each customer's balance current; totals go to the general ledger at month-end.")
q('E-7-1','c7',"A check mark (✓) in the PR column of the sales journal means the amount was:",["Posted to the customer's subsidiary ledger account","Not yet posted","Posted to the Sales account","Paid in cash"],"Subsidiary ledger accounts are usually not numbered, so a check mark is used.")
q('QS-7-7','c7',"In the cash receipts journal, the total of the \"Other Accounts\" credit column is:",["Not posted; each amount is posted individually","Posted to Cash","Posted to Accounts Receivable","Posted to Sales"],"The column holds many different accounts, so only the individual amounts are posted.")
q('QS-7-11','c7',"A company returns $400 of merchandise to a supplier for credit on account (perpetual). It is recorded in the general journal as:",["Dr Accounts Payable 400; Cr Merchandise Inventory 400","Dr Merchandise Inventory 400; Cr Accounts Payable 400","Dr Accounts Payable 400; Cr Purchases Returns 400 in the purchases journal","Dr Cash 400; Cr Merchandise Inventory 400"],"Returns are not routine purchases, so they go to the general journal. The posting also updates the supplier's subsidiary account.")
q('E-7-7','c7',"A $2,000 invoice (2/10, n/30) is paid within the discount period. In the cash disbursements journal (perpetual) the amounts are:",["Accounts Payable Dr 2,000; Merchandise Inventory Cr 40; Cash Cr 1,960","Accounts Payable Dr 1,960; Cash Cr 1,960","Cash Dr 1,960; Accounts Payable Cr 2,000","Accounts Payable Dr 2,000; Cash Cr 2,000"],"The discount reduces inventory cost under a perpetual system.")
q('QS-7-13','c7',"Accounts payable $24,000; cost of sales $292,000. Days' payable outstanding (365 days)?",["30 days","12 days","82 days","24 days"],"24,000 ÷ 292,000 × 365 = 30.")
# ---------- Chapter 8: cash and internal control (non-reconciliation) ----------
q('QS-8-1','c8',"Which is NOT an objective of internal control?",["Guarantee that the company is profitable","Protect assets","Ensure reliable accounting","Promote efficient operations and urge adherence to policies"],"Internal control gives reasonable assurance; it cannot guarantee profit.")
q('QS-8-5','c8',"The register tape shows sales of $1,200, but $1,208 is in the drawer. Entry?",["Dr Cash 1,208; Cr Cash Over and Short 8; Cr Sales 1,200","Dr Cash 1,208; Cr Sales 1,208","Dr Cash 1,200; Dr Cash Over and Short 8; Cr Sales 1,208","Dr Cash 1,200; Cr Sales 1,200"],"An overage is a credit to Cash Over and Short (miscellaneous revenue).")
q('E-8-9','c8',"A $250 petty cash fund holds $40 cash and receipts for supplies $90, postage $70 and delivery $55. How much is the overage or shortage?",["Overage of $5 (credit Cash Over and Short)","Shortage of $5 (debit Cash Over and Short)","No difference","Shortage of $40"],"Receipts 215 + cash 40 = 255, which is $5 more than the 250 fund. Replenish 210: Dr Supplies 90, Postage 70, Delivery 55; Cr Cash Over and Short 5; Cr Cash 210.")
q('P-8-3A','c8',"When a $200 petty cash fund is replenished, management also increases it to $300. Which account is debited for the increase?",["Petty Cash, $100","Cash, $100","Miscellaneous Expense, $100","Cash Over and Short, $100"],"Petty Cash changes only when the fund is set up or its size changes.")
q('QS-8-33A','c8',"In a voucher system, which document starts the purchasing process?",["Purchase requisition","Purchase order","Invoice","Receiving report"],"Order: requisition → purchase order → invoice → receiving report → invoice approval → voucher.")
q('QS-8-35','c8',"Accounts receivable $18,000; net sales $219,000. Days' sales uncollected (365 days)?",["30 days","12 days","82 days","18 days"],"18,000 ÷ 219,000 × 365 = 30.")
# ---------- Chapter 9: receivables ----------
q('QS-9-2','c9',"Goods are sold for $5,000 on a bank credit card with a 3% fee; cash is received immediately. Entry?",["Dr Cash 4,850; Dr Credit Card Expense 150; Cr Sales 5,000","Dr Cash 5,000; Cr Sales 5,000","Dr Accounts Receivable 5,000; Cr Sales 5,000","Dr Cash 4,850; Cr Sales 4,850"],"The card fee is an expense of the seller.")
q('QS-9-3','c9',"Direct write-off method: a $800 customer account is written off. Entry?",["Dr Bad Debts Expense 800; Cr Accounts Receivable 800","Dr Allowance for Doubtful Accounts 800; Cr Accounts Receivable 800","Dr Accounts Receivable 800; Cr Bad Debts Expense 800","Dr Bad Debts Expense 800; Cr Allowance for Doubtful Accounts 800"],"With no allowance account, the expense is recorded at write-off.")
q('QS-9-4','c9',"Direct write-off: the $800 written off earlier is recovered in the same year. First entry?",["Dr Accounts Receivable 800; Cr Bad Debts Expense 800","Dr Cash 800; Cr Bad Debts Expense 800","Dr Allowance 800; Cr Accounts Receivable 800","Dr Cash 800; Cr Sales 800"],"Reinstate the account, then record Dr Cash 800, Cr Accounts Receivable 800.")
q('QS-9-5','c9',"Why is the allowance method preferred to the direct write-off method?",["It matches estimated bad debts with the sales of the same period","It never requires estimates","It records bad debts only when certain","It increases reported receivables"],"Direct write-off is acceptable only when bad debts are immaterial.")
q('QS-9-6','c9',"Allowance method: a $600 account is written off. Effect on the net realizable value of receivables?",["No change","Decreases by $600","Increases by $600","Decreases by $1,200"],"Dr Allowance 600, Cr Accounts Receivable 600 reduces both by the same amount.")
q('QS-9-7','c9',"Accounts receivable $50,000; allowance for doubtful accounts $2,500. Amount reported as net receivables?",["$47,500","$50,000","$52,500","$2,500"],"Net realizable value = 50,000 − 2,500.")
q('QS-9-8','c9',"Accounts receivable $80,000; 4% are estimated uncollectible. The allowance has a $1,100 credit balance before adjustment. Bad debts expense?",["$2,100","$3,200","$4,300","$1,100"],"Required allowance 3,200 − existing 1,100 = 2,100.")
q('QS-9-8','c9',"Same estimate ($3,200 required), but the allowance has a $500 debit balance before adjustment. Bad debts expense?",["$3,700","$2,700","$3,200","$500"],"The adjustment must cover the debit balance too: 3,200 + 500 = 3,700.")
q('QS-9-9','c9',"Credit sales are $300,000; bad debts are estimated at 1% of credit sales. The allowance has a $1,100 credit balance. Bad debts expense?",["$3,000","$1,900","$4,100","$1,100"],"The percent-of-sales method ignores the existing allowance balance.")
q('QS-9-1','c9',"Aging: 0–30 days $40,000 (1%); 31–60 days $15,000 (5%); 61–90 days $6,000 (15%); over 90 days $3,000 (40%). The allowance has an $800 credit balance. Bad debts expense?",["$2,450","$3,250","$4,050","$800"],"Required 400 + 750 + 900 + 1,200 = 3,250; 3,250 − 800 = 2,450.")
q('E-9-6','c9',"Allowance method: a $600 account written off earlier is collected. Entries?",["Dr Accounts Receivable 600, Cr Allowance 600; then Dr Cash 600, Cr Accounts Receivable 600","Dr Cash 600, Cr Bad Debts Expense 600","Dr Cash 600, Cr Allowance 600 only","Dr Allowance 600, Cr Cash 600"],"Reinstate the account, then record the collection.")
q('QS-9-22','c9',"A 90-day note is dated March 10. What is its maturity date?",["June 8","June 10","June 9","June 7"],"March 21 days + April 30 + May 31 = 82; 8 more days → June 8.")
q('QS-9-23','c9',"A $6,000, 90-day, 8% note is honored at maturity (360-day year). Entry?",["Dr Cash 6,120; Cr Notes Receivable 6,000; Cr Interest Revenue 120","Dr Cash 6,480; Cr Notes Receivable 6,000; Cr Interest Revenue 480","Dr Cash 6,000; Cr Notes Receivable 6,000","Dr Notes Receivable 6,120; Cr Cash 6,120"],"Interest = 6,000 × 8% × 90/360 = 120.")
q('E-9-26','c9',"The same $6,000, 90-day, 8% note is dishonored at maturity. Entry?",["Dr Accounts Receivable 6,120; Cr Interest Revenue 120; Cr Notes Receivable 6,000","Dr Bad Debts Expense 6,000; Cr Notes Receivable 6,000","Dr Accounts Receivable 6,000; Cr Notes Receivable 6,000","No entry until the maker pays"],"The maker still owes principal plus interest, so both move to Accounts Receivable.")
q('QS-9-24','c9',"A $9,000, 60-day, 10% note is dated December 16. Accrued interest at December 31 (360-day year)?",["$37.50","$150.00","$75.00","$40.00"],"9,000 × 10% × 15/360 = 37.50.")
q('QS-9-25','c9',"A company factors $20,000 of receivables for a 2% fee. Entry?",["Dr Cash 19,600; Dr Factoring Fee Expense 400; Cr Accounts Receivable 20,000","Dr Cash 20,000; Cr Accounts Receivable 20,000","Dr Cash 19,600; Cr Notes Payable 19,600","Dr Cash 19,600; Cr Accounts Receivable 19,600"],"Selling receivables removes them; the fee is an expense.")
q('E-9-27','c9',"A company borrows using its receivables as security (pledging). How are the receivables reported?",["They stay on the balance sheet, and the pledge is disclosed","They are removed from the balance sheet","They become a contra-liability","They are reported as cash"],"Pledging is a loan; the company still owns the receivables.")
q('QS-9-28','c9',"Net sales $360,000; accounts receivable $28,000 at the start and $32,000 at the end of the year. Accounts receivable turnover?",["12.0 times","11.25 times","12.9 times","6.0 times"],"Average AR 30,000; 360,000 ÷ 30,000 = 12.0.")
q('E-9-4','c9',"Sales made on the company's own store credit card are recorded as:",["Dr Accounts Receivable; Cr Sales","Dr Cash; Cr Sales","Dr Credit Card Expense; Cr Sales","Dr Notes Receivable; Cr Sales"],"The company grants the credit itself, so it holds the receivable.")
for t in T: assert len(set(t['opts']))==4,t['q']
print(len(T))
from collections import Counter; print(Counter(t['cat'] for t in T))
json.dump(T,open('/tmp/gen/tb.json','w'),ensure_ascii=False)
